{
  "name": "opencode-azure-devops-pr-review",
  "version": "0.5.0",
  "type": "module",
  "description": "Azure DevOps PR reviews from a URL in OpenCode, with no checkout, review passes on the models you choose, and comment previews you can adjust before posting",
  "scripts": {
    "test": "node --test tests/*.test.mjs",
    "check": "node --check src/session.mjs && node --check src/runtime.mjs && node --check src/comment-data.mjs && node --check src/comment-work.mjs && node --check src/comments.mjs && node --check src/config.mjs && node --check src/output.mjs && node --check src/diagnostics.mjs && node --check src/attribution.mjs && node --check src/host.mjs && node --check src/tool-queue.mjs && node --check src/azure.mjs && node --check src/diff.mjs && node --check src/search.mjs && node --check src/review-tools.mjs && node --check src/review-work.mjs && node --check src/store.mjs && node --check src/plugin.js && node --check src/setup.mjs && node --check src/tui-model.mjs && node --check src/tui-setup.mjs && node --check src/tui-actions.mjs && node --check src/tui.js && node --check server.js && node --check scripts/build-tui.mjs && node scripts/build-tui.mjs --check && sh -n install.sh && sh -n uninstall.sh",
    "build:tui": "node scripts/build-tui.mjs"
  },
  "engines": {
    "node": ">=22.12.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/WTLAIB/opencode-azure-devops-pr-review-v2.git"
  },
  "homepage": "https://github.com/WTLAIB/opencode-azure-devops-pr-review-v2#readme",
  "bugs": {
    "url": "https://github.com/WTLAIB/opencode-azure-devops-pr-review-v2/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "azure-devops",
    "code-review",
    "pull-request",
    "opencode-plugins",
    "azure-repos",
    "ai-code-review"
  ],
  "license": "MIT",
  "exports": {
    ".": "./server.js",
    "./tui": "./src/tui.js"
  },
  "files": [
    "server.js",
    "src/",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "babel-preset-solid": "1.9.16"
  }
}

import { PLUGIN_ID } from './config.mjs';
import { setupPlugin } from './setup.mjs';

// Pure OpenCode V2 definition; the host supplies its domain APIs.
export default {
  id: PLUGIN_ID,
  setup: setupPlugin,
};
